mapper.select:
SELECT ADMIN_ID AS adminId, PASSWORD AS password,
ADMIN_NAME AS adminName, ROLE AS role
FROM admin WHERE ADMIN_ID = #{adminId}

SELECT I.INQUIRY_ID, I.USER_ID, I.TITLE, I.CONTENT, I.INQUIRY_STATUS AS STATUS, R.CONTENT AS ANSWER, DATE_FORMAT(I.CREATED_AT, '%Y-%m-%d %H:%i') AS CREATED_AT, (SELECT GROUP_CONCAT(IMG_URL) FROM inquiry_img WHERE INQUIRY_ID = I.INQUIRY_ID) AS IMG_URLS FROM inquiry I LEFT OUTER JOIN inquiry_reply R ON I.INQUIRY_ID = R.INQUIRY_ID
AND I.INQUIRY_STATUS = #{status}
ORDER BY I.INQUIRY_ID DESC

mapper.insert:
INSERT INTO inquiry_reply (INQUIRY_ID, CONTENT, CREATED_AT)
VALUES (#{inquiryId}, #{answer}, NOW())
ON DUPLICATE KEY UPDATE CONTENT = #{answer}

mapper.select:
SELECT USER_ID AS userId, USER_NAME AS userName, EMAIL AS email,
USER_PHONE AS userPhone, NICKNAME AS nickname, SOCIAL_TYPE AS
socialType, GRADE_ID AS gradeId, USER_STATUS AS userStatus, POINT AS
point, TOTAL_AMOUNT AS totalAmount, DATE_FORMAT(CREATED_AT, '%Y-%m-%d')
AS createdAt, MARKETING_YN AS marketingYn FROM USER 

		AND (USER_ID LIKE CONCAT('%', #{keyword}, '%')
		OR USER_NAME LIKE CONCAT('%', #{keyword}, '%'))


		AND GRADE_ID = #{gradeId}


		AND USER_STATUS = #{status}


		AND USER_STATUS = #{userStatus}


ORDER BY CREATED_AT DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM USER 

		AND (USER_ID LIKE CONCAT('%', #{keyword}, '%')
		OR USER_NAME LIKE CONCAT('%', #{keyword}, '%'))


		AND GRADE_ID = #{gradeId}


		AND USER_STATUS = #{status}


		AND USER_STATUS = #{userStatus}

SELECT p.PRODUCT_ID, p.PRODUCT_NAME, p.PRODUCT_TYPE, p.PRICE, p.DEPOSIT, p.DESCRIPTION, p.VIEW_COUNT, p.IS_AVAILABLE, p.BRAND_ID, p.CATEGORY_ID, DATE_FORMAT(p.CREATED_AT, '%Y-%m-%d') AS CREATED_AT, (SELECT IMG_URL FROM product_img pi WHERE pi.PRODUCT_ID = p.PRODUCT_ID LIMIT 1) AS IMG_URL, (SELECT CAPACITY FROM product_spec ps WHERE ps.PRODUCT_ID = p.PRODUCT_ID LIMIT 1) AS CAPACITY, (SELECT SIZE FROM product_spec ps WHERE ps.PRODUCT_ID = p.PRODUCT_ID LIMIT 1) AS SIZE, (SELECT WEIGHT FROM product_spec ps WHERE ps.PRODUCT_ID = p.PRODUCT_ID LIMIT 1) AS WEIGHT, (SELECT MATERIAL FROM product_spec ps WHERE ps.PRODUCT_ID = p.PRODUCT_ID LIMIT 1) AS MATERIAL, (SELECT ORIGIN FROM product_spec ps WHERE ps.PRODUCT_ID = p.PRODUCT_ID LIMIT 1) AS ORIGIN, (SELECT TITLE FROM product_feature pf WHERE pf.PRODUCT_ID = p.PRODUCT_ID LIMIT 1) AS FEATURE_TITLE, (SELECT CONTENT FROM product_feature pf WHERE pf.PRODUCT_ID = p.PRODUCT_ID LIMIT 1) AS FEATURE_CONTENT FROM product p
AND p.PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%')
AND p.PRODUCT_TYPE = #{productType}
ORDER BY p.PRODUCT_ID DESC LIMIT #{offset}, #{pageSize}

 SELECT COUNT(*) FROM product 

				AND PRODUCT_NAME LIKE CONCAT('%', #{keyword}, '%')


				AND PRODUCT_TYPE = #{productType}

mapper.update:
UPDATE PRODUCT_OPTION_ITEM
SET IS_AVAILABLE = #{isAvailable}
WHERE OPTION_ITEM_ID = #{optionItemId}

mapper.select:
SELECT O.ORDER_ID, O.USER_ID, DATE_FORMAT(O.CREATED_AT, '%Y-%m-%d %H:%i') AS CREATED_AT, O.TOTAL_PRICE, O.ORDER_STATUS, GROUP_CONCAT(P.PRODUCT_NAME ORDER BY OI.ITEM_ID ASC SEPARATOR ', ') AS PRODUCT_NAME, ( SELECT PI.IMG_URL FROM ORDER_ITEM OI2 JOIN PRODUCT_IMG PI ON PI.PRODUCT_ID = OI2.PRODUCT_ID WHERE OI2.ORDER_ID = O.ORDER_ID ORDER BY PI.IS_MAIN DESC LIMIT 1 ) AS IMG_URL FROM ORDERS O LEFT JOIN ORDER_ITEM OI ON O.ORDER_ID = OI.ORDER_ID LEFT JOIN PRODUCT P ON OI.PRODUCT_ID = P.PRODUCT_ID
AND ( CAST(O.ORDER_ID AS CHAR) LIKE CONCAT('%', #{keyword}, '%') OR O.USER_ID LIKE CONCAT('%', #{keyword}, '%') )
GROUP BY O.ORDER_ID, O.USER_ID, O.CREATED_AT, O.TOTAL_PRICE, O.ORDER_STATUS ORDER BY O.CREATED_AT DESC LIMIT #{offset}, #{pageSize}

mapper.update:
UPDATE RENTALS
SET RENTAL_STATUS = #{status}
WHERE RENTAL_ID = #{rentalId}
AND RENTAL_STATUS IN ('RETURN_REQUESTED', 'RETURN_PICKED',
'RETURN_COMPLETED', 'IN_USE')

UPDATE PAYMENT
SET PAY_STATUS = 'REFUNDED'
WHERE ORDER_ID = #{orderId}

UPDATE refund
SET REFUND_STATUS = #{status}
WHERE REFUND_ID = #{refundId}

mapper.select:
SELECT C.*, I.IMG_URL FROM camp C
LEFT JOIN camp_img I ON C.CAMP_ID = I.CAMP_ID AND I.IS_MAIN = 'Y'
WHERE C.CAMP_ID = #{campId}

mapper.update:
UPDATE camp SET CAMP_NAME = #{campName}, ADDRESS = #{campAddress},
INDUTY = #{campType}, DESCRIPTION = #{campContent}
WHERE CAMP_ID = #{campId}

UPDATE event
SET TITLE = #{title}, CONTENT = #{content},
START_DATE = #{start_date}, END_DATE = #{end_date}
WHERE EVENT_ID = #{eventId}

mapper.select:
SELECT uc.USER_COUPON_ID, uc.USER_ID, u.USER_NAME, c.COUPON_NAME, uc.USED_YN, uc.STATUS, DATE_FORMAT(uc.ISSUED_AT, '%Y-%m-%d %H:%i') AS ISSUED_AT, DATE_FORMAT(uc.EXPIRED_AT, '%Y-%m-%d') AS EXPIRED_AT FROM user_coupon uc JOIN coupon c ON uc.COUPON_ID = c.COUPON_ID JOIN user u ON uc.USER_ID = u.USER_ID AND uc.USER_ID = #{userId}
AND (u.USER_NAME LIKE CONCAT('%', #{keyword}, '%') OR c.COUPON_NAME LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY uc.CREATED_AT DESC

SELECT A.ALARM_ID AS alarmId, A.USER_ID AS userId, A.TYPE AS type,
A.TITLE AS title, A.CONTENT AS content, A.LINK_ID AS linkId, A.LINK_URL
AS linkUrl, A.IS_READ AS isRead, DATE_FORMAT(A.CREATED_AT, '%m/%d
%H:%i') AS createdAt FROM alarm A 

		AND A.TYPE = #{type}


ORDER BY A.ALARM_ID DESC LIMIT #{offset}, #{pageSize}
